// ---------------------------------------------------------------- flags
const flag = (inner, w = 60, h = 40) => `<svg class="lflag" viewBox="0 0 ${w} ${h}">${inner}<rect width="${w}" height="${h}" fill="none" stroke="#9db4c6" stroke-width="1"/></svg>`;
const pennant = (inner) => `<svg class="lflag" viewBox="0 0 70 40"><defs><clipPath id="pn${Math.random().toString(36).slice(2, 7)}"><path d="M0,0 L70,14 L70,26 L0,40 Z"/></clipPath></defs>${inner}<path d="M0,0 L70,14 L70,26 L0,40 Z" fill="none" stroke="#9db4c6"/></svg>`;
const F = {
  P: flag('<rect width="60" height="40" fill="#1f4fbf"/><rect x="18" y="12" width="24" height="16" fill="#fff"/>'),
  I: flag('<rect width="60" height="40" fill="#f6d000"/><circle cx="30" cy="20" r="10" fill="#111"/>'),
  Z: flag('<path d="M0,0 L60,0 L30,20 Z" fill="#f6d000"/><path d="M60,0 L60,40 L30,20 Z" fill="#1f4fbf"/><path d="M0,40 L60,40 L30,20 Z" fill="#d22"/><path d="M0,0 L0,40 L30,20 Z" fill="#111"/>'),
  U: flag('<rect width="60" height="40" fill="#fff"/><rect width="30" height="20" fill="#d22"/><rect x="30" y="20" width="30" height="20" fill="#d22"/>'),
  BLACK: flag('<rect width="60" height="40" fill="#111"/>'),
  X: flag('<rect width="60" height="40" fill="#fff"/><rect x="24" width="12" height="40" fill="#1f4fbf"/><rect y="14" width="60" height="12" fill="#1f4fbf"/>'),
  N: flag('<rect width="60" height="40" fill="#fff"/>' + [0, 1, 2, 3].flatMap((r) => [0, 1, 2, 3].map((c) => ((r + c) % 2 ? '' : `<rect x="${c * 15}" y="${r * 10}" width="15" height="10" fill="#1f4fbf"/>`))).join('')),
  S: flag('<rect width="60" height="40" fill="#fff"/><rect x="18" y="12" width="24" height="16" fill="#1f4fbf"/>'),
  C: flag('<rect width="60" height="40" fill="#1f4fbf"/><rect y="8" width="60" height="24" fill="#fff"/><rect y="16" width="60" height="8" fill="#d22"/>'),
  Y: flag('<rect width="60" height="40" fill="#f6d000"/>' + [-40, -20, 0, 20, 40, 60].map((x) => `<path d="M${x},40 L${x + 10},40 L${x + 50},0 L${x + 40},0 Z" fill="#d22"/>`).join('')),
  AP: pennant('<path d="M0,0 L70,14 L70,26 L0,40 Z" fill="#fff"/>' + [0, 14, 28, 42, 56].map((x, i) => (i % 2 ? '' : `<rect x="${x}" y="0" width="14" height="40" fill="#d22" clip-path="none"/>`)).join('').replace(/clip-path="none"/g, '')),
  ORANGE: flag('<rect width="60" height="40" fill="#ff8a00"/>'),
  BLUE: flag('<rect width="60" height="40" fill="#1f4fbf"/>'),
};
// AP: keep stripes inside the pennant outline.
F.AP = `<svg class="lflag" viewBox="0 0 70 40"><defs><clipPath id="apc"><path d="M0,0 L70,14 L70,26 L0,40 Z"/></clipPath></defs><g clip-path="url(#apc)"><rect width="70" height="40" fill="#fff"/>${[0, 28, 56].map((x) => `<rect x="${x}" width="14" height="40" fill="#d22"/>`).join('')}</g><path d="M0,0 L70,14 L70,26 L0,40 Z" fill="none" stroke="#9db4c6"/></svg>`;

